import{_ as a,o as l,c as i,ai as n}from"./chunks/framework.ampVZV4B.js";const b=JSON.parse('{"title":"Electron 面试 · 桌面与上位机","description":"","frontmatter":{},"headers":[],"relativePath":"guide/nodejs/electron-interview.md","filePath":"guide/nodejs/electron-interview.md"}'),r={name:"guide/nodejs/electron-interview.md"};function t(s,e,d,o,c,h){return l(),i("div",null,[...e[0]||(e[0]=[n(`<h1 id="electron-面试-·-桌面与上位机" tabindex="-1">Electron 面试 · 桌面与上位机 <a class="header-anchor" href="#electron-面试-·-桌面与上位机" aria-label="Permalink to “Electron 面试 · 桌面与上位机”">​</a></h1><blockquote><p>对你简历里「Electron 上位机」很关键，建议能讲满 5 分钟。</p></blockquote><hr><h2 id="高频问法" tabindex="-1">高频问法 <a class="header-anchor" href="#高频问法" aria-label="Permalink to “高频问法”">​</a></h2><ol><li>Electron 主进程、渲染进程、预加载脚本？</li><li>为什么强调安全（contextIsolation / contextBridge）？</li><li>主进程和渲染进程怎么通信？</li><li>崩溃、卡死怎么排查？</li><li>自动更新、打包你了解多少？</li><li>上位机连设备时架构怎么放？</li></ol><hr><h2 id="口述参考" tabindex="-1">口述参考 <a class="header-anchor" href="#口述参考" aria-label="Permalink to “口述参考”">​</a></h2><h3 id="_1-三层" tabindex="-1">1）三层 <a class="header-anchor" href="#_1-三层" aria-label="Permalink to “1）三层”">​</a></h3><table tabindex="0"><thead><tr><th>角色</th><th>职责</th></tr></thead><tbody><tr><td>主进程</td><td>窗口生命周期、菜单、部分原生/设备、单例</td></tr><tr><td>渲染进程</td><td>UI（可 Vue）</td></tr><tr><td>preload</td><td>中间桥：只暴露安全 API 给页面</td></tr></tbody></table><h3 id="_2-安全" tabindex="-1">2）安全 <a class="header-anchor" href="#_2-安全" aria-label="Permalink to “2）安全”">​</a></h3><ul><li><code>nodeIntegration: false</code></li><li><code>contextIsolation: true</code></li><li>用 <code>contextBridge.exposeInMainWorld</code> 暴露有限方法</li></ul><p>页面若能直接 <code>require(&#39;fs&#39;)</code>，XSS ≈ 本地任意代码执行。</p><h3 id="_3-ipc" tabindex="-1">3）IPC <a class="header-anchor" href="#_3-ipc" aria-label="Permalink to “3）IPC”">​</a></h3><p><code>ipcMain</code> / <code>ipcRenderer</code>（经 preload 包装）。<br> 约定：渲染发「请求」，主进程执行特权操作后回传。<br> 别把整颗 Node 能力透出。</p><h3 id="_4-排查" tabindex="-1">4）排查 <a class="header-anchor" href="#_4-排查" aria-label="Permalink to “4）排查”">​</a></h3><ul><li>主进程日志与渲染 DevTools 分开看</li><li>卡死：是不是主进程同步堵了、设备读写死等</li><li>崩溃：看 crash dump / 版本兼容（Electron 大版本跨度大）</li></ul><h3 id="_5-打包与更新" tabindex="-1">5）打包与更新 <a class="header-anchor" href="#_5-打包与更新" aria-label="Permalink to “5）打包与更新”">​</a></h3><p>知道 electron-builder 一类打包；自动更新要签名与喂养渠道。<br> 面试说「我们用过打包发布，细节按项目」即可，没有就别编。</p><h3 id="_6-上位机-设备-重点" tabindex="-1">6）上位机 + 设备（重点） <a class="header-anchor" href="#_6-上位机-设备-重点" aria-label="Permalink to “6）上位机 + 设备（重点）”">​</a></h3><p>推荐口述架构：</p><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>设备(PLC/仪表)</span></span>
<span class="line"><span>  ↔ 主进程或独立 Node 子进程（协议、重连、队列）</span></span>
<span class="line"><span>  ↔ IPC/本地端口</span></span>
<span class="line"><span>  ↔ 渲染进程 UI（状态展示、人工操作）</span></span>
<span class="line"><span>  ↔ 可选：上报 Java 后端 / MQTT</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>要点：</p><ul><li>协议与 UI 解耦</li><li>超时、断线重连、点表配置化</li><li>写设备要确认，防误操作</li></ul><p>可链：<a href="/my-vitepress-site/tech-system/integration/modbus-tcp-node-plc.html">Modbus Node</a></p><hr><h2 id="追问预备" tabindex="-1">追问预备 <a class="header-anchor" href="#追问预备" aria-label="Permalink to “追问预备”">​</a></h2><ul><li>「为什么不用纯 Web？」→ 要本地权限、连现场设备、离线。</li><li>「和 Java 客户端比？」→ 前端栈复用快；复杂工业可 Java+WebView，我们选 Electron 是团队技能折中。</li></ul>`,27)])])}const u=a(r,[["render",t]]);export{b as __pageData,u as default};
